'use strict';
for(const [course,file,prefix] of [['AHAD','AHAD Term 1 Seminar Notes.docx','ahad-seminar-20261016-'],['Thera','Theraputics Seminars.docx','thera-seminar-20261016-']]){
 if(!STUDY_ADDITIONS.sources.some(s=>s.file===file))STUDY_ADDITIONS.sources.push({course,file,source:'sources/'+file,kind:'Seminar notes',status:'Imported October 16: all body text, tables and supported embedded images. Original claims retained; curated questions identify conflicts separately.',modules:STUDY_CONTENT.modules.filter(m=>m.id.startsWith(prefix)).map(m=>m.id)});
}
